请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-011

=== 用户原始指令 (query.txt) ===
我下周六有场羽毛球俱乐部联赛，帮我做个赛事提醒卡。左边信息区大字"距离比赛还有3天"，右边动作区放一个日历图标按钮。整体用清晨运动感的蓝绿渐变，下方再纵向排列两块不同底色的小区块：第一块写比赛地点和对手，第二块显示我已完成热身打卡，标"运动手环已连接"。点日历按钮直接跳日历看日程。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "我下周六有场羽毛球俱乐部联赛，帮我做个赛事提醒卡。左边信息区大字\"距离比赛还有3天\"，右边动作区放一个日历图标按钮。整体用清晨运动感的蓝绿渐变，下方再纵向排列两块不同底色的小区块：第一块写比赛地点和对手，第二块显示我已完成热身打卡，标\"运动手环已连接\"。点日历按钮直接跳日历看日程。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "calendar-event-badminton-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "ui": {
      "eventName": {
        "type": "string",
        "description": "赛事名称展示文本",
        "sampleValue": "羽毛球俱乐部联赛"
      },
      "countdownText": {
        "type": "string",
        "description": "距离比赛开始的倒计时展示文本",
        "sampleValue": "距离比赛还有3天"
      },
      "warmupStatus": {
        "type": "string",
        "description": "热身打卡完成状态",
        "sampleValue": "已完成热身打卡"
      },
      "deviceStatus": {
        "type": "string",
        "description": "运动手环连接状态",
        "sampleValue": "运动手环已连接"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程索引项唯一标识符，用于打开日程详情",
              "sampleValue": "calendar-event-badminton-001"
            },
            "title": {
              "type": "string",
              "description": "日程标题",
              "sampleValue": "羽毛球俱乐部联赛"
            },
            "eventLocation": {
              "type": "string",
              "description": "比赛地点",
              "sampleValue": "星河运动中心"
            },
            "description": {
              "type": "string",
              "description": "比赛补充描述，可承载对手信息",
              "sampleValue": "青木俱乐部"
            },
            "dtStart": {
              "type": "string",
              "description": "比赛开始时间",
              "sampleValue": "09:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "比赛结束时间",
              "sampleValue": "11:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合用于查看日程或打开日历事件的图标按钮。"
    }
  ]
}

